import React from "react";

export default function EventCard({ event, onClick }) {
  return (
    <div className="event-card" style={{
      padding: 16,
      border: "1px solid #ddd",
      borderRadius: 10,
      width: 300,
      margin: 10,
      background: "white"
    }}>
      <h3>{event.title}</h3>
      <p>{event.shortDescription || "Click below to know more."}</p>

      <button
        onClick={onClick}
        style={{
          marginTop: 10,
          padding: "8px 14px",
          background: "#0077cc",
          color: "white",
          border: "none",
          borderRadius: 6,
          cursor: "pointer",
        }}
      >
        View Event
      </button>
    </div>
  );
}
